create type public.lead_status as enum ('new','analyzed','qualified','contacted','interested','meeting','won','lost');
create type public.run_status as enum ('pending','running','completed','failed','waiting_for_approval');
create type public.approval_status as enum ('pending','approved','rejected');

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, company_name text, timezone text default 'Europe/Athens', created_at timestamptz not null default now());
create table public.leads (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, business_name text not null, category text, city text, country text default 'Greece', website text, email text, phone text, google_maps_url text, source text not null default 'demo', status public.lead_status not null default 'new', score smallint check(score between 0 and 100), score_reason text, opportunity_summary text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.lead_analysis (id uuid primary key default gen_random_uuid(), lead_id uuid not null references public.leads(id) on delete cascade, website_quality text, mobile_quality text, online_booking text, cta_quality text, online_presence text, problems jsonb not null default '[]', opportunities jsonb not null default '[]', analysis_json jsonb not null default '{}', created_at timestamptz not null default now());
create table public.interactions (id uuid primary key default gen_random_uuid(), lead_id uuid not null references public.leads(id) on delete cascade, direction text not null, channel text not null, subject text, content text, status text not null default 'draft', created_at timestamptz not null default now());
create table public.tasks (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null, description text, lead_id uuid references public.leads(id) on delete set null, status text not null default 'open', priority text not null default 'medium', due_at timestamptz, created_at timestamptz not null default now());
create table public.jarvis_runs (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, request text not null, status public.run_status not null default 'pending', summary text, started_at timestamptz, completed_at timestamptz, created_at timestamptz not null default now());
create table public.jarvis_run_steps (id uuid primary key default gen_random_uuid(), run_id uuid not null references public.jarvis_runs(id) on delete cascade, step_order integer not null, title text not null, description text, status public.run_status not null default 'pending', tool_name text, input_json jsonb, output_json jsonb, started_at timestamptz, completed_at timestamptz, unique(run_id, step_order));
create table public.approvals (id uuid primary key default gen_random_uuid(), run_id uuid not null references public.jarvis_runs(id) on delete cascade, action_type text not null, payload jsonb not null default '{}', status public.approval_status not null default 'pending', approved_at timestamptz, created_at timestamptz not null default now());
create table public.activity_logs (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, event_type text not null, title text not null, description text, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table public.settings (user_id uuid primary key references auth.users(id) on delete cascade, default_language text not null default 'en', target_industries text[] not null default '{}', target_locations text[] not null default '{}', minimum_lead_score smallint not null default 70 check(minimum_lead_score between 0 and 100), company_services text[] not null default '{}', company_description text);
create index leads_user_score_idx on public.leads(user_id, score desc); create index leads_user_status_idx on public.leads(user_id, status); create index runs_user_created_idx on public.jarvis_runs(user_id, created_at desc); create index activity_user_created_idx on public.activity_logs(user_id, created_at desc);

alter table public.profiles enable row level security; alter table public.leads enable row level security; alter table public.lead_analysis enable row level security; alter table public.interactions enable row level security; alter table public.tasks enable row level security; alter table public.jarvis_runs enable row level security; alter table public.jarvis_run_steps enable row level security; alter table public.approvals enable row level security; alter table public.activity_logs enable row level security; alter table public.settings enable row level security;
create policy "own profile" on public.profiles for all using (auth.uid() = id) with check (auth.uid() = id);
create policy "own leads" on public.leads for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "own analysis through lead" on public.lead_analysis for all using (exists (select 1 from public.leads where leads.id = lead_analysis.lead_id and leads.user_id = auth.uid()));
create policy "own interactions through lead" on public.interactions for all using (exists (select 1 from public.leads where leads.id = interactions.lead_id and leads.user_id = auth.uid()));
create policy "own tasks" on public.tasks for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "own runs" on public.jarvis_runs for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "own run steps" on public.jarvis_run_steps for all using (exists (select 1 from public.jarvis_runs where jarvis_runs.id = jarvis_run_steps.run_id and jarvis_runs.user_id = auth.uid()));
create policy "own approvals through run" on public.approvals for all using (exists (select 1 from public.jarvis_runs where jarvis_runs.id = approvals.run_id and jarvis_runs.user_id = auth.uid()));
create policy "own activity" on public.activity_logs for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "own settings" on public.settings for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
